# Versioned schemas and synchronous migrations

Add a distinct TypeBox `TVersioned` schema with a linear synchronous migration history. Export the complete contract through `typebox/type`, and expose its values on `Type`:

```ts
export type TVersion = string | number
export interface TVersionInitial<Version extends TVersion = TVersion, Schema extends TSchema = TSchema> { version: Version; schema: Schema }
export interface TVersionStep<Version extends TVersion = TVersion, Schema extends TSchema = TSchema, Migration extends Function = Function> extends TVersionInitial<Version, Schema> { migrate: Migration }
export interface TVersioned<Key extends string = string, History extends readonly TVersionInitial[] = readonly TVersionInitial[], Current extends TSchema = TSchema> extends TSchema { '~kind': 'Versioned'; runtime: 'in-process'; versionKey: Key; current: Current; history: History; toJSON(): never }
export type TVersionMigration<Source extends TSchema, Target extends TSchema> = (value: Static<Source>) => Static<Target>
export class VersionedBuilder<Key extends string, History extends readonly TVersionInitial[], Current extends TSchema> {
  Migrate<const Version extends TVersion, const Next extends TSchema>(version: Version, schema: Next, migrate: TVersionMigration<Current, Next>): VersionedBuilder<Key, readonly [...History, TVersionStep<Version, Next, TVersionMigration<Current, Next>>], Next>
  Schema(): TVersioned<Key, History, Current>
}
